package projects.chess.strategy;

import projects.chess.enums.Team;
import projects.chess.models.*;


public class KingMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int rowDiff = Math.abs(toRow - fromRow);
        int colDiff = Math.abs(toCol - fromCol);
        boolean stayedPut = rowDiff == 0 && colDiff == 0;
        boolean isOneStep = rowDiff <= 1 && colDiff <= 1;
        if (!isOneStep || stayedPut){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

package projects.chess.strategy;

import projects.chess.enums.Team;
import projects.chess.models.*;

public class KnightMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int colDiff = Math.abs(toCol - fromCol);
        int rowDiff = Math.abs(toRow - fromRow);
        boolean isLShape = (rowDiff == 2 && colDiff == 1) || (rowDiff == 1 && colDiff == 2);
        if (!isLShape){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

package projects.chess.strategy;

import java.util.EnumMap;
import java.util.Map;
import projects.chess.enums.ChessPiece;

public class MoveStrategyFactory {
    private static final Map<ChessPiece, IMoveStrategy> STRATEGIES = new EnumMap<>(ChessPiece.class);

    static {
        STRATEGIES.put(ChessPiece.PAWN, new PawnMoveStrategy());
        STRATEGIES.put(ChessPiece.KNIGHT, new KnightMoveStrategy());
        STRATEGIES.put(ChessPiece.ROOK, new RookMoveStrategy());
        STRATEGIES.put(ChessPiece.BISHOP, new BishopMoveStrategy());
        STRATEGIES.put(ChessPiece.QUEEN, new QueenMoveStrategy());
        STRATEGIES.put(ChessPiece.KING, new KingMoveStrategy());
    }


    public static IMoveStrategy getStrategy(ChessPiece piece){
        IMoveStrategy strategy = STRATEGIES.get(piece);
        if (strategy == null) {
            throw new IllegalArgumentException("No move strategy registered for piece " + piece);
        }
        return strategy;
    }
}

package projects.chess.strategy;

import projects.chess.enums.Team;
import projects.chess.models.*;

public class PawnMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int colDiff = Math.abs(toCol - fromCol);
        int rowDiff = toRow - fromRow;
        int direction = team == Team.WHITE ? 1 : -1;

        if(colDiff == 0 && rowDiff == 2 * direction && (fromRow == 1 || fromRow == 6)){
            int midRow = fromRow + direction;
            return board.getTeamAt(midRow, fromCol) == Team.NONE && board.getTeamAt(toRow, toCol) == Team.NONE;
        }
        else if(colDiff == 0 && rowDiff == direction){
            return board.getTeamAt(toRow, toCol) == Team.NONE;
        }
        else if(colDiff == 1 && rowDiff == direction){
            return board.getTeamAt(toRow, toCol) != team && board.getTeamAt(toRow, toCol) != Team.NONE;
        }
        return false;
    }
}

package projects.chess.strategy;

import projects.chess.enums.Team;
import projects.chess.models.*;

public class QueenMoveStrategy implements IMoveStrategy {
    private final IMoveStrategy rookMove = new RookMoveStrategy();
    private final IMoveStrategy bishopMove = new BishopMoveStrategy();

    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        return rookMove.isValidMove(board, fromRow, fromCol, toRow, toCol, team)
            || bishopMove.isValidMove(board, fromRow, fromCol, toRow, toCol, team);
    }
}

package projects.chess.strategy;

import projects.chess.enums.Team;
import projects.chess.models.*;

public class RookMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        boolean sameRow = fromRow == toRow;
        boolean sameCol = fromCol == toCol;
        boolean stayedPut = sameRow && sameCol;
        if ((!sameRow && !sameCol) || stayedPut){
            return false;
        }
        if (!board.isPathClear(fromRow, fromCol, toRow, toCol)){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

