// ===== projects/chess/services/GameService.java =====
class GameService {
    private final IGameRepository repository;

    public GameService(IGameRepository repo) {
        this.repository = repo;
    }

    public String createGame(User whitePlayer, User blackPlayer){
        Game game = new Game(whitePlayer, blackPlayer);
        repository.save(game);
        return game.getId();
    }

    public Game getGame(String gameId){
        Game game = this.repository.getById(gameId);
        if (game == null) {
            throw new IllegalArgumentException("No game found with id " + gameId);
        }
        return game;
    }

    public void move(String gameId, int fromRow, int fromCol, int toRow, int toCol){
        Game game = getGame(gameId);
        if (game.getGameStatus() != GameStatus.IN_PROGRESS) {
            System.err.println("Game is not in progress, cannot move");
            return;
        }

        Board board = game.getBoard();
        ChessPiece piece = board.getPieceAt(fromRow, fromCol);
        Team movingTeam = board.getTeamAt(fromRow, fromCol);
        Team currentTeam = game.getCurrentPlayer() == game.getWhitePlayer() ? Team.WHITE : Team.BLACK;

        if (piece == ChessPiece.NONE) {
            System.err.println("No piece at (" + fromRow + "," + fromCol + ")");
            return;
        }
        if (movingTeam != currentTeam) {
            System.err.println(game.getCurrentPlayer().getName() + " cannot move the opponent's piece");
            return;
        }

        IMoveStrategy strategy = MoveStrategyFactory.getStrategy(piece);
        if (!strategy.isValidMove(board, fromRow, fromCol, toRow, toCol, movingTeam)) {
            System.err.println("Invalid move for " + piece + " from (" + fromRow + "," + fromCol + ") to (" + toRow + "," + toCol + ")");
            return;
        }

        board.movePiece(fromRow, fromCol, toRow, toCol);
        this.switchPlayer(game);
    }

    private void switchPlayer(Game game){
        if (game.getCurrentPlayer() == game.getWhitePlayer()) {
            game.setCurrentPlayer(game.getBlackPlayer());
        } else {
            game.setCurrentPlayer(game.getWhitePlayer());
        }
    }
}

// ===== projects/chess/strategy/BishopMoveStrategy.java =====
class BishopMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int rowDiff = Math.abs(toRow - fromRow);
        int colDiff = Math.abs(toCol - fromCol);
        if (rowDiff == 0 || rowDiff != colDiff){
            return false;
        }
        if (!board.isPathClear(fromRow, fromCol, toRow, toCol)){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

// ===== projects/chess/strategy/IMoveStrategy.java =====
interface IMoveStrategy {
    boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team);
}

// ===== projects/chess/strategy/KingMoveStrategy.java =====
class KingMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int rowDiff = Math.abs(toRow - fromRow);
        int colDiff = Math.abs(toCol - fromCol);
        boolean stayedPut = rowDiff == 0 && colDiff == 0;
        boolean isOneStep = rowDiff <= 1 && colDiff <= 1;
        if (!isOneStep || stayedPut){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

// ===== projects/chess/strategy/KnightMoveStrategy.java =====
class KnightMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int colDiff = Math.abs(toCol - fromCol);
        int rowDiff = Math.abs(toRow - fromRow);
        boolean isLShape = (rowDiff == 2 && colDiff == 1) || (rowDiff == 1 && colDiff == 2);
        if (!isLShape){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}

// ===== projects/chess/strategy/MoveStrategyFactory.java =====
class MoveStrategyFactory {
    private static final Map<ChessPiece, IMoveStrategy> STRATEGIES = new EnumMap<>(ChessPiece.class);

    static {
        STRATEGIES.put(ChessPiece.PAWN, new PawnMoveStrategy());
        STRATEGIES.put(ChessPiece.KNIGHT, new KnightMoveStrategy());
        STRATEGIES.put(ChessPiece.ROOK, new RookMoveStrategy());
        STRATEGIES.put(ChessPiece.BISHOP, new BishopMoveStrategy());
        STRATEGIES.put(ChessPiece.QUEEN, new QueenMoveStrategy());
        STRATEGIES.put(ChessPiece.KING, new KingMoveStrategy());
    }


    public static IMoveStrategy getStrategy(ChessPiece piece){
        IMoveStrategy strategy = STRATEGIES.get(piece);
        if (strategy == null) {
            throw new IllegalArgumentException("No move strategy registered for piece " + piece);
        }
        return strategy;
    }
}

// ===== projects/chess/strategy/PawnMoveStrategy.java =====
class PawnMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        int colDiff = Math.abs(toCol - fromCol);
        int rowDiff = toRow - fromRow;
        int direction = team == Team.WHITE ? 1 : -1;

        if(colDiff == 0 && rowDiff == 2 * direction && (fromRow == 1 || fromRow == 6)){
            int midRow = fromRow + direction;
            return board.getTeamAt(midRow, fromCol) == Team.NONE && board.getTeamAt(toRow, toCol) == Team.NONE;
        }
        else if(colDiff == 0 && rowDiff == direction){
            return board.getTeamAt(toRow, toCol) == Team.NONE;
        }
        else if(colDiff == 1 && rowDiff == direction){
            return board.getTeamAt(toRow, toCol) != team && board.getTeamAt(toRow, toCol) != Team.NONE;
        }
        return false;
    }
}

// ===== projects/chess/strategy/QueenMoveStrategy.java =====
class QueenMoveStrategy implements IMoveStrategy {
    private final IMoveStrategy rookMove = new RookMoveStrategy();
    private final IMoveStrategy bishopMove = new BishopMoveStrategy();

    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        return rookMove.isValidMove(board, fromRow, fromCol, toRow, toCol, team)
            || bishopMove.isValidMove(board, fromRow, fromCol, toRow, toCol, team);
    }
}

// ===== projects/chess/strategy/RookMoveStrategy.java =====
class RookMoveStrategy implements IMoveStrategy {
    @Override
    public boolean isValidMove(Board board, int fromRow, int fromCol, int toRow, int toCol, Team team){
        boolean sameRow = fromRow == toRow;
        boolean sameCol = fromCol == toCol;
        boolean stayedPut = sameRow && sameCol;
        if ((!sameRow && !sameCol) || stayedPut){
            return false;
        }
        if (!board.isPathClear(fromRow, fromCol, toRow, toCol)){
            return false;
        }
        return board.getTeamAt(toRow, toCol) != team;
    }
}
